/* Department-owned QR18-13-D monthly sheet. All groups share the same daily records. */
(()=>{
const words={
cadre:['QR18-13 幹部日常管理點檢表','QR18-13 Cadres daily checklist','QR18-13 Lista diaria de mandos','QR18-13 Phiếu kiểm tra quản lý hằng ngày'],
cadreHelp:['各組通用，每個部門每月一張。點選日期或格子填寫當日紀錄。','One monthly sheet per department, shared by all groups. Select a date or cell to enter results.','Una hoja mensual por departamento para todos los grupos. Seleccione una fecha o celda.','Mỗi bộ phận dùng chung một bảng mỗi tháng. Chọn ngày hoặc ô để ghi kết quả.'],
cadreDefaultNA:['過去日期未填寫，預設顯示 NA；僅為顯示，可補登實際結果。','Past date not entered: default NA display only; actual results can be entered later.','Fecha pasada sin registrar: NA solo visual; se pueden registrar resultados reales después.','Ngày đã qua chưa nhập: NA chỉ để hiển thị; có thể bổ sung kết quả thực tế.'],
cadreBoard:['目視化看板','Visual board','Tablero visual','Bảng trực quan'],cadreFill:['填寫點檢','Enter inspection','Registrar inspección','Nhập kiểm tra'],
cadreUnit:['使用單位','Department','Departamento','Bộ phận'],cadreMonth:['年月','Year / month','Año / mes','Năm / tháng'],
cadreItem:['稽核項目','Check item','Ítem de auditoría','Mục kiểm tra'],cadreStandard:['判定基準','Judging standard','Criterio de evaluación','Tiêu chuẩn đánh giá'],cadreDate:['點檢日期','Check date','Fecha de inspección','Ngày kiểm tra'],
cadreNormal:['正常／符合要求','Normal / meets requirements','Normal / cumple','Bình thường / đạt yêu cầu'],cadreIssue:['缺失／待改善','Needs improvement','Requiere mejora','Thiếu sót / cần cải thiện'],cadreFixed:['已改善完成','Improvement completed','Mejora completada','Đã cải thiện'],cadreNA:['不適用','Not applicable','No aplica','Không áp dụng'],cadreBlank:['未填寫','Not entered','Sin registrar','Chưa nhập'],
cadreFillNormal:['一鍵點檢（空白填入正常）','One-click check (fill blanks as normal)','Inspección con un clic (completar vacíos como normal)','Kiểm tra một lần (điền bình thường vào ô trống)'],
cadreFillNormalHelp:['僅填入當日空白項目，保留已填結果與備註。請實際查核後確認並儲存。','Only blank items for this date are filled. Existing results and notes are preserved. Check the items before confirming and saving.','Solo se completan los ítems vacíos de esta fecha. Se conservan resultados y notas. Revise antes de confirmar y guardar.','Chỉ điền các mục trống của ngày đã chọn. Giữ nguyên kết quả và ghi chú. Kiểm tra thực tế trước khi xác nhận và lưu.'],
cadreFillNormalDone:['已填入正常：{count} 項，尚未儲存。','Filled as normal: {count} items. Not saved yet.','Completados como normal: {count} ítems. Aún sin guardar.','Đã điền bình thường: {count} mục. Chưa lưu.'],
cadreFillNormalEmpty:['沒有空白項目，原有紀錄已保留。','No blank items. Existing results were preserved.','No hay ítems vacíos. Se conservaron los resultados.','Không có mục trống. Giữ nguyên kết quả hiện có.'],
cadreDuty:['值班人員確認','Confirmed by duty officer','Confirmación del responsable de turno','Nhân viên trực ca xác nhận'],cadreSupervisor:['主管確認','Supervisor confirmation','Confirmación del supervisor','Quản lý xác nhận'],
cadreRule:['PS.早上需巡視記錄，當記錄待改善時（符號先打 ∖），需當日改善完畢，下班前再確認完成才能修改為已改善符號 Φ。','Inspect and record in the morning. Mark issues ∖ first, complete improvements the same day and confirm before leaving work to change the symbol to Φ.','Inspeccione por la mañana. Marque ∖, complete la mejora ese día y confirme antes de salir para cambiar a Φ.','Kiểm tra và ghi vào buổi sáng. Ghi ∖ khi cần cải thiện, hoàn thành trong ngày và xác nhận trước khi tan ca để đổi sang Φ.'],
cadreSign:['我已查核當日全部項目，確認並簽名。','I reviewed all items for this date and confirm my signature.','He revisado todos los ítems de esta fecha y confirmo mi firma.','Tôi đã kiểm tra tất cả mục trong ngày và xác nhận ký tên.'],
cadreSave:['儲存當日紀錄','Save daily record','Guardar registro diario','Lưu bản ghi trong ngày'],cadreSaved:['當日紀錄已儲存','Daily record saved','Registro guardado','Đã lưu bản ghi'],cadreLoading:['讀取部門月表…','Loading department sheet…','Cargando hoja…','Đang tải bảng…'],
cadreFailed:['無法讀取月表，請重新整理。','Could not load the sheet. Refresh to retry.','No se pudo cargar. Actualice.','Không tải được bảng. Vui lòng tải lại.'],cadreRetry:['重新讀取','Reload','Recargar','Tải lại'],
cadreConflict:['紀錄已由其他人更新。請關閉並重新讀取月表，再核對後修改；本次尚未儲存。','Someone updated this record. Close and reload the sheet before editing again. Your changes were not saved.','Otro usuario actualizó el registro. Cierre y recargue antes de editar. No se guardaron los cambios.','Người khác đã cập nhật. Đóng và tải lại bảng để kiểm tra. Thay đổi chưa được lưu.'],
cadreImproveFirst:['請先儲存「∖ 待改善」，實際改善完成後才能改為 Φ。','Save ∖ first; change it to Φ after the improvement is completed.','Guarde ∖ primero; cambie a Φ cuando termine la mejora.','Lưu ∖ trước; sau khi cải thiện xong mới đổi sang Φ.'],
cadreIncomplete:['請填值班人員姓名。主管確認時，需填妥 所有項目及主管姓名。','Enter the duty officer name. Supervisor confirmation requires all items and the supervisor name.','Indique el responsable. La confirmación requiere todos los ítems y el nombre del supervisor.','Nhập tên người trực. Xác nhận quản lý cần đủ các mục và tên quản lý.'],
cadreSaveFailed:['儲存未完成，請重試。若其他人已更新，請重新讀取。','Save failed. Retry, or reload if another person updated the record.','No se guardó. Reintente o recargue si hubo cambios.','Chưa lưu được. Thử lại hoặc tải lại nếu có người cập nhật.'],
cadreDiscard:['有尚未儲存的內容，確定關閉？','Discard unsaved changes?','¿Descartar cambios sin guardar?','Bỏ thay đổi chưa lưu?'],
cadreNote:['備註／改善說明（選填）','Notes / improvement details (optional)','Notas / mejora (opcional)','Ghi chú / cải thiện (không bắt buộc)'],cadreNoDept:['目前沒有可使用的部門。','No department available.','No hay departamento disponible.','Không có bộ phận khả dụng.'],
cadrePrint:['列印月表','Print monthly sheet','Imprimir hoja mensual','In bảng tháng'],cadreFull:['放大看板','Expand board','Ampliar tablero','Mở rộng bảng'],cadreClose:['關閉','Close','Cerrar','Đóng'],cadreZoom:['看板縮放','Board zoom','Zoom del tablero','Thu phóng bảng'],cadreLegend:['填表說明／符號','Instructions / symbols','Instrucciones / símbolos','Hướng dẫn / ký hiệu'],cadreReadOnly:['點選「填寫點檢」後可修改紀錄。','Select Enter inspection to edit records.','Seleccione Registrar inspección para editar.','Chọn Nhập kiểm tra để sửa bản ghi.']
};
for(const[k,v]of Object.entries(words))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,i)=>[l,v[i]]));
const symbols=['','V','∖','Φ','N/A'],labels=['cadreBlank','cadreNormal','cadreIssue','cadreFixed','cadreNA'];
const ml=v=>formContentHtml(v);
let templateItems=structuredClone(CADRE_TEMPLATE.items),templateRevision=0;
const isCadre=()=>['cadre','cadreManage'].includes(view);
const editable=()=>view==='cadreManage'&&canManage();
const sameItem=(a,b)=>a?.id===b?.id&&['name','standard'].every(k=>['zh','en','es','vi'].every(l=>(formContent(a[k])?.[l]||'')===(formContent(b[k])?.[l]||'')));
let dept='',month=inspectionDay().slice(0,7),records=[],ticket=0,mode='board',zoom=100,loadedKey='',lastCountry='';
const oldRender=render;
render=function(){if(profile&&!canManage()&&view==='cadreManage')view='board';oldRender();};
const oldContent=renderContent;
renderContent=function(){if(isCadre()&&profile&&activeCountry){renderCadre();return;}ticket++;return oldContent();};
const key=()=>[activeCountry,countryGeneration,profile?.account_id,dept,month].join(':');
function options(){return data.departments.filter(d=>d.is_active!==false&&accessDepartment(d.id,'cadre'));}
async function renderCadre(){
 const countryKey=activeCountry+':'+countryGeneration;if(lastCountry!==countryKey){lastCountry=countryKey;dept='';loadedKey='';records=[];}
 if(!editable())mode='board';
 const ds=options();if(!ds.some(d=>d.id===dept))dept=ds.find(d=>d.id===profile.department_id)?.id||ds[0]?.id||'';
 $('#content').innerHTML=`<section class="cadre-page"><p>${txt('cadreHelp')}</p><p class="muted">${txt('cadreDefaultNA')}</p><div class="filter-row cadre-toolbar"><label>${txt('cadreUnit')} <select id="cadreDept" class="select">${ds.map(d=>`<option value="${esc(d.id)}" ${d.id===dept?'selected':''}>${esc(nameOf(d))}</option>`).join('')}</select></label><label>${txt('cadreMonth')} <input id="cadreMonth" type="month" class="select" min="2000-01" max="2099-12" value="${month}"></label><button id="cadreReload" class="btn secondary">${txt('cadreRetry')}</button><button id="cadreMode" class="btn primary">${txt(mode==='board'?'cadreFill':'cadreBoard')}</button><button id="cadrePrint" class="btn secondary" disabled>${txt('cadrePrint')}</button><button id="cadreFull" class="btn secondary">${txt('cadreFull')}</button><label>${txt('cadreZoom')} <select id="cadreZoom" class="select">${[40,60,80,100].map(n=>`<option ${n===zoom?'selected':''} value="${n}">${n}%</option>`).join('')}</select></label></div><p id="cadreMessage" role="status"></p><div id="cadreBoard"></div></section>`;
 $('#cadreDept').onchange=e=>{dept=e.target.value;loadedKey='';renderCadre();};
 $('#cadreMonth').onchange=e=>{if(/^20\d{2}-(0[1-9]|1[0-2])$/.test(e.target.value)){month=e.target.value;loadedKey='';renderCadre();}};
 $('#cadreReload').onclick=()=>{loadedKey='';renderCadre();};
 $('#cadreMode').hidden=!editable();
 if(editable()){$('#cadreMode').insertAdjacentHTML('afterend',`<button id="cadreTemplateEdit" class="btn secondary">${formHtml('f40_59')}</button>`);$('#cadreTemplateEdit').onclick=editTemplate;}
 $('#cadreMode').onclick=()=>{mode=mode==='board'?'edit':'board';renderCadre();};
 $('#cadreZoom').onchange=e=>{zoom=+e.target.value;const s=$('.cadre-paper');if(s)s.style.zoom=zoom/100;};
 $('#cadreFull').onclick=()=>{$('.cadre-page').classList.toggle('expanded');$('#cadreFull').innerHTML=txt($('.cadre-page').classList.contains('expanded')?'cadreClose':'cadreFull');};
 $('#cadrePrint').onclick=()=>{document.body.classList.add('printing-cadre');window.print();document.body.classList.remove('printing-cadre');};
 if(!dept){$('#cadreMessage').innerHTML=txt('cadreNoDept');return;}
 const requestKey=key(),requestTicket=++ticket;
 if(loadedKey!==requestKey){$('#cadreMessage').innerHTML=txt('cadreLoading');try{const result=await api({action:'cadre_month',department_id:dept,month});if(requestTicket!==ticket||key()!==requestKey||!isCadre())return;records=result.records;templateItems=result.template?.items||structuredClone(CADRE_TEMPLATE.items);templateRevision=result.template?.revision||0;loadedKey=requestKey;}catch(e){if(requestTicket===ticket&&isCadre())$('#cadreMessage').innerHTML=txt('cadreFailed');return;}}
 if(requestTicket!==ticket)return;
 drawSheet();$('#cadreMessage').innerHTML=mode==='board'?txt('cadreReadOnly'):txt('cadreHelp');$('#cadrePrint').disabled=false;
}
function drawSheet(){
 const sheetItems=[...templateItems];for(const r of records)for(const item of r.template_snapshot||CADRE_TEMPLATE.items)if(!sheetItems.some(x=>sameItem(x,item)))sheetItems.push(item);
 function resultAt(r,index){const k=(r?.template_snapshot||CADRE_TEMPLATE.items).findIndex(x=>sameItem(x,sheetItems[index]));return k<0?null:r?.results?.[k];}

 const n=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate(),byDay=new Map(records.map(r=>[Number(r.inspection_date.slice(8)),r]));
 const days=Array.from({length:31},(_,i)=>i+1),unit=options().find(d=>d.id===dept),current=visualToday();
 function cell(day,index){const r=byDay.get(day),v=resultAt(r,index)?.value||'',note=resultAt(r,index)?.note||'',date=month+'-'+String(day).padStart(2,'0');const valid=day<=n,editable=valid&&date<=current&&mode==='edit',defaultNA=valid&&!v&&date<current,displayValue=defaultNA?'NA':v,label=defaultNA?'cadreDefaultNA':labels[symbols.indexOf(v)];return `<td class="cadre-result s${defaultNA?4:symbols.indexOf(v)} ${valid?'':'cadre-unused'}"><button ${editable?'':'disabled'} data-cadre-day="${day}" data-cadre-item="${index}" aria-label="${esc(date+' '+(index+1)+'. '+t(label))}" title="${esc(note||t(label))}">${valid?esc(displayValue):'—'}${note&&valid?'<span class="cadre-note-dot" aria-hidden="true">•</span>':''}</button></td>`;}
 $('#cadreBoard').innerHTML=`<div class="cadre-scroll" tabindex="0" aria-label="${esc(t('cadreBoard'))}"><article class="cadre-paper" style="zoom:${zoom/100}"><header class="cadre-sheet-head"><img src="/cadre-logo.png" alt="NES Limited"><h2>${txt('cadre')}</h2><div>${txt('cadreUnit')}：${esc(nameOf(unit))}<br>${month.slice(0,4)} / ${month.slice(5)}<small>${CADRE_TEMPLATE.code}</small></div></header><table class="cadre-sheet"><colgroup><col style="width:42px"><col style="width:280px"><col style="width:650px">${days.map(()=>'<col style="width:44px">').join('')}</colgroup><thead><tr><th rowspan="2">NO</th><th rowspan="2">${txt('cadreItem')}</th><th rowspan="2">${txt('cadreStandard')}</th><th colspan="31">${txt('cadreDate')}</th></tr><tr>${days.map(d=>`<th class="${d>n?'cadre-unused':''}"><button data-cadre-day="${d}" ${mode==='edit'&&d<=n&&month+'-'+String(d).padStart(2,'0')<=current?'':'disabled'}>${d}</button></th>`).join('')}</tr></thead><tbody>${sheetItems.map((item,i)=>`<tr><th scope="row">${item.id}</th><td class="cadre-item">${ml(item.name)}${!templateItems.some(x=>sameItem(x,item))?`<small>${formHtml('f40_60')}</small>`:''}</td><td class="cadre-standard">${ml(item.standard)}</td>${days.map(d=>cell(d,i)).join('')}</tr>`).join('')}<tr><td colspan="2" rowspan="3" class="cadre-legend"><strong>${txt('cadreLegend')}</strong>${symbols.slice(1).map((s,i)=>`<p>${esc(s)}　${txt(labels[i+1])}</p>`).join('')}</td><th>${txt('cadreDuty')}</th>${days.map(d=>`<td class="cadre-sign ${d>n?'cadre-unused':''}">${esc(byDay.get(d)?.duty_name||'')}</td>`).join('')}</tr><tr><th>${txt('cadreSupervisor')}</th>${days.map(d=>`<td class="cadre-sign ${d>n?'cadre-unused':''}" title="${esc(byDay.get(d)?.confirmed_at||'')}">${esc(byDay.get(d)?.supervisor_name||'')}</td>`).join('')}</tr><tr><td colspan="32" class="cadre-rule">${txt('cadreRule')}</td></tr></tbody></table></article></div>`;
 $$('[data-cadre-day]').forEach(b=>b.onclick=()=>openDay(Number(b.dataset.cadreDay),Number(b.dataset.cadreItem||0)));
}
function editTemplate(){
 if(!editable()||loadedKey!==key())return;
 const requestKey=key(),savedDept=dept,savedMonth=month,revision=templateRevision;let draft=templateItems.map(x=>({...x,name:formContent(x.name),standard:formContent(x.standard)})),saving=false;
 const dialog=document.createElement('div');dialog.className='modal open cadre-modal';
 dialog.innerHTML=`<section class="dialog" role="dialog" aria-modal="true"><header class="dialog-head"><h2>${formHtml('f40_61')} · ${month}</h2><button id="templateClose" class="x">×</button></header><form id="templateForm"><div class="dialog-body"><p>${formHtml('f40_62')}</p><div id="templateRows"></div><button type="button" class="btn secondary" id="templateAdd">${formHtml('f40_63')}</button><p id="templateMessage" role="alert"></p></div><footer class="dialog-foot"><button class="btn primary" type="submit">${formHtml('f40_64')}</button></footer></form></section>`;
 document.body.append(dialog);
 function rows(){dialog.querySelector('#templateRows').innerHTML=draft.map((x,i)=>`<section class="item"><h3>${formHtml('f40_65')} ${i+1}</h3>${['name','standard'].map(k=>`<label>${k==='name'?formText('f40_66'):formText('f40_67')}<textarea required maxlength="${k==='name'?500:5000}" data-index="${i}" data-field="${k}">${esc(x[k].zh||'')}</textarea></label>`).join('')}<details><summary>${formHtml('f40_68')}</summary>${['en','es','vi'].map(l=>['name','standard'].map(k=>`<label>${esc(localeNames[l])} · ${k==='name'?formText('f40_65'):formText('f40_69')}<textarea maxlength="5000" data-index="${i}" data-field="${k}" data-lang="${l}">${esc(x[k][l]||'')}</textarea></label>`).join('')).join('')}</details></section>`).join('');}
 rows();dialog.querySelector('#templateRows').oninput=e=>{if(e.target.dataset.field)draft[+e.target.dataset.index][e.target.dataset.field][e.target.dataset.lang||'zh']=e.target.value;};
 dialog.querySelector('#templateAdd').onclick=()=>{if(draft.length>=200)return;draft.push({id:draft.length+1,name:{zh:''},standard:{zh:''}});rows();dialog.querySelector('#templateRows').lastElementChild.scrollIntoView();};
 dialog.querySelector('#templateClose').onclick=()=>{if(!saving&&confirm(formText('f40_70')))dialog.remove();};
 dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();if(saving||key()!==requestKey)return;saving=true;dialog.querySelectorAll('button,textarea').forEach(x=>x.disabled=true);try{const r=await api({action:'cadre_template_save',department_id:savedDept,month:savedMonth,revision,items:draft});if(key()!==requestKey)return;templateItems=r.template.items;templateRevision=r.template.revision;dialog.remove();drawSheet();}catch(e){dialog.querySelector('#templateMessage').textContent=e.message.includes('record_changed')?formText('f40_71'):formText('f40_72');}finally{saving=false;dialog.querySelectorAll('button,textarea').forEach(x=>x.disabled=false);}};
}
function openDay(day,focusItem){
 const date=month+'-'+String(day).padStart(2,'0'),r=records.find(x=>x.inspection_date===date),requestKey=key(),savedDept=dept;
 const dayItems=r?.template_snapshot||templateItems;focusItem=Math.min(focusItem,dayItems.length-1);
 const canWrite=()=>editable()&&key()===requestKey&&accessCan(savedDept,'cadre',r?'edit':'create');
 if(mode!=='edit'||date>inspectionDay()||!canWrite())return;
 let dirty=false,saving=false;
 const dialog=document.createElement('div');dialog.className='modal open cadre-modal';dialog.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-labelledby="cadreDialogTitle"><header class="dialog-head"><div><h2 id="cadreDialogTitle">${txt('cadre')} · ${date}</h2><p>${esc(nameOf(options().find(x=>x.id===dept)))}</p></div><button class="x" id="cadreCancel" aria-label="${esc(t('cadreClose'))}">×</button></header><form id="cadreForm" class="cadre-form"><div class="dialog-body">${powerCheckButton('cadreFillNormal','id="cadreFillNormal"')}<div class="notice">${txt('cadreRule')}</div><div class="cadre-batch-actions"><p>${txt('cadreFillNormalHelp')}</p><p id="cadreBatchMessage" role="status" aria-live="polite"></p></div>${dayItems.map((item,i)=>`<section class="item" id="cadreItem${i}"><h3>${item.id}. ${ml(item.name)}</h3><p class="cadre-standard">${ml(item.standard)}</p><label>${txt('cadreItem')} ${item.id} <select class="select" name="result${i}" aria-label="${esc(t('cadreItem')+' '+item.id)}">${symbols.map((s,j)=>`<option value="${esc(s)}" ${(r?.results[i]?.value||'')===s?'selected':''} ${s==='Φ'&&!['∖','Φ'].includes(r?.results[i]?.value)?'disabled':''}>${esc(s?s+' '+t(labels[j]):t(labels[j]))}</option>`).join('')}</select></label><label class="cadre-note-label">${txt('cadreNote')}<textarea name="note${i}" maxlength="2000" rows="2">${esc(r?.results[i]?.note||'')}</textarea></label></section>`).join('')}<div class="cadre-sign-fields"><label>${txt('cadreDuty')}<input name="duty" maxlength="100" required value="${esc(r?.duty_name||'')}"></label><label>${txt('cadreSupervisor')}<input name="supervisor" maxlength="100" value="${esc(r?.supervisor_name||'')}"></label></div><label class="cadre-confirm"><input type="checkbox" name="confirmed">${txt('cadreSign')}</label></div><footer class="dialog-foot"><p id="cadreSaveMessage" role="alert"></p><button type="submit" id="cadreSave" class="btn primary">${txt('cadreSave')}</button></footer></form></section>`;
 document.body.append(dialog);const form=dialog.querySelector('form');const close=()=>{if(saving)return;if(dirty&&!confirm(t('cadreDiscard')))return;dialog.remove();};
 $('#cadreCancel').onclick=close;dialog.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const nodes=[...dialog.querySelectorAll('button:not(:disabled),input,select,textarea')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};
 dialog.querySelector('#cadreFillNormal').onclick=()=>{
 if(saving||!canWrite())return;
 let count=0;for(let i=0;i<dayItems.length;i++){const field=form.elements['result'+i];if(field.value===''){field.value='V';count++;}}
 if(count){dirty=true;form.elements.confirmed.checked=false;}
 dialog.querySelector('#cadreBatchMessage').innerHTML=count?txt('cadreFillNormalDone').replaceAll('{count}',String(count)):txt('cadreFillNormalEmpty');
 };
 form.oninput=e=>{dirty=true;if(e.target.name!=='confirmed')form.elements.confirmed.checked=false;};
 setTimeout(()=>{dialog.querySelector('#cadreItem'+focusItem)?.scrollIntoView({block:'start'});form.elements['result'+focusItem].focus({preventScroll:true});},0);
 form.onsubmit=async e=>{e.preventDefault();if(saving||!canWrite())return;
 const results=dayItems.map((it,i)=>({id:it.id,value:form.elements['result'+i].value,note:form.elements['note'+i].value.trim()})),duty=form.elements.duty.value.trim(),supervisor=form.elements.supervisor.value.trim(),confirmed=form.elements.confirmed.checked;
 if(!duty||(confirmed&&(!supervisor||results.some(x=>!x.value)))){$('#cadreSaveMessage').innerHTML=txt('cadreIncomplete');return;}
 saving=true;form.querySelectorAll('input,select,textarea,button').forEach(el=>el.disabled=true);$('#cadreCancel').disabled=true;
 try{const saved=await api({action:'cadre_save',department_id:savedDept,inspection_date:date,revision:r?.revision||0,results,duty_name:duty,supervisor_name:supervisor,confirmed,template_version:CADRE_TEMPLATE.version,template_revision:templateRevision});if(key()!==requestKey)return;records=records.filter(x=>x.inspection_date!==date);records.push(saved.record);dialog.remove();drawSheet();$('#cadreMessage').innerHTML=txt('cadreSaved');}
 catch(error){const message=error.message||'';$('#cadreSaveMessage').innerHTML=txt(message.includes('record_changed')?'cadreConflict':message.includes('improvement_requires_issue')?'cadreImproveFirst':message.includes('confirmation_incomplete')||message.includes('invalid_cadre_record')?'cadreIncomplete':'cadreSaveFailed');if(message.includes('record_changed'))loadedKey='';}
 finally{saving=false;if(dialog.isConnected){form.querySelectorAll('input,select,textarea,button').forEach(el=>el.disabled=false);$('#cadreCancel').disabled=false;}}
 };
}
})();
